{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || path.join(root, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );
`);
// Add archive state to databases created by earlier task checkpoints.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
if (!projectColumns.some((column) => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'");
}
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
}
if (!taskColumns.some((column) => column.name === 'due_date')) {
  database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}
if (!taskColumns.some((column) => column.name === 'sort_order')) {
  database.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER');
  database.exec('UPDATE tasks SET sort_order = id');
}
if (!taskColumns.some((column) => column.name === 'notes')) {
  database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!taskColumns.some((column) => column.name === 'deleted')) {
  database.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0');
}
database.exec('PRAGMA foreign_keys = ON');
// Keep a task's position in every project it has visited. The task's current
// project can change, but these rows preserve its place for a later return.
database.exec(`
  CREATE TABLE IF NOT EXISTS task_project_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id)
  );
  INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
    SELECT id, project_id, sort_order FROM tasks;
`);

const indexHtml = await readFile(path.join(root, 'index.html'));
const clientJs = await readFile(path.join(root, 'app.js'));
const css = await readFile(path.join(root, 'style.css'));

function sendJson(res, status, value) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return sendJson(res, 200, database.prepare(`
      SELECT p.id, p.name, p.archived, p.default_priority AS defaultPriority,
        COUNT(CASE WHEN t.deleted = 0 THEN 1 END) AS totalCount,
        COALESCE(SUM(CASE WHEN t.deleted = 0 AND t.completed = 1 THEN 1 ELSE 0 END), 0) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id
    `).all().map((project) => ({ ...project, id: Number(project.id), archived: Boolean(project.archived), totalCount: Number(project.totalCount), completedCount: Number(project.completedCount) })));
  }
  if (url.pathname === '/api/projects/active' && req.method === 'GET') {
    return sendJson(res, 200, database.prepare('SELECT id, name FROM projects WHERE archived = 0 ORDER BY id').all().map((p) => ({ ...p, id: Number(p.id) })));
  }
  if (url.pathname === '/api/directory' && req.method === 'GET') {
    return sendJson(res, 200, database.prepare(`
      SELECT t.id, t.project_id AS projectId, p.name AS projectName, p.archived,
        t.title, t.completed, t.priority, t.due_date AS dueDate, t.notes, t.deleted
      FROM projects p JOIN tasks t ON t.project_id = p.id
      LEFT JOIN task_project_positions pos ON pos.task_id = t.id AND pos.project_id = t.project_id
      ORDER BY p.id, COALESCE(pos.position, t.sort_order), t.id
    `).all().map((task) => ({ ...task, id: Number(task.id), projectId: Number(task.projectId), archived: Boolean(task.archived), completed: Boolean(task.completed), deleted: Boolean(task.deleted), priority: task.priority || 'Normal', dueDate: task.dueDate || '', notes: task.notes || '' })));
  }
  if (url.pathname === '/api/directory/bulk' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    if (typeof data.completed !== 'boolean' || !Array.isArray(data.taskIds) || data.taskIds.some((id) => !Number.isInteger(id))) {
      return sendJson(res, 400, { error: 'Invalid bulk update' });
    }
    const update = database.prepare(`UPDATE tasks SET completed = ? WHERE id = ? AND deleted = 0
      AND project_id IN (SELECT id FROM projects WHERE archived = 0)`);
    database.exec('BEGIN IMMEDIATE');
    try {
      for (const id of new Set(data.taskIds)) update.run(data.completed ? 1 : 0, id);
      database.exec('COMMIT');
    } catch (error) {
      database.exec('ROLLBACK');
      throw error;
    }
    return sendJson(res, 200, { updated: data.taskIds.length });
  }
  if (url.pathname === '/api/projects/import' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid project JSON' }); }
    const override = typeof data.importedName === 'string' ? data.importedName.trim() : '';
    if (!override) return sendJson(res, 400, { error: 'Project name is required' });
    const priorities = ['Low', 'Normal', 'High'];
    const doc = data.document;
    const valid = doc && typeof doc === 'object' && !Array.isArray(doc) &&
      doc.format === 'workboard-project' && doc.version === 1 && Number.isInteger(doc.version) &&
      doc.project && typeof doc.project === 'object' && !Array.isArray(doc.project) &&
      typeof doc.project.name === 'string' && doc.project.name.trim() &&
      typeof doc.project.archived === 'boolean' && priorities.includes(doc.project.defaultPriority) &&
      Array.isArray(doc.project.tasks) && doc.project.tasks.every((task) =>
        task && typeof task === 'object' && !Array.isArray(task) &&
        typeof task.title === 'string' && task.title.trim() &&
        typeof task.completed === 'boolean' && priorities.includes(task.priority) &&
        typeof task.dueDate === 'string' && (!task.dueDate || isValidDate(task.dueDate)) &&
        typeof task.notes === 'string' && typeof task.deleted === 'boolean');
    if (!valid) return sendJson(res, 400, { error: 'Invalid project JSON' });
    let projectId;
    try {
      database.exec('BEGIN IMMEDIATE');
      const created = database.prepare('INSERT INTO projects (name, archived, default_priority) VALUES (?, ?, ?)')
        .run(override, doc.project.archived ? 1 : 0, doc.project.defaultPriority);
      projectId = Number(created.lastInsertRowid);
      const insertTask = database.prepare(`INSERT INTO tasks
        (project_id, title, completed, priority, due_date, notes, deleted, sort_order)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)`);
      const insertPosition = database.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)');
      doc.project.tasks.forEach((task, index) => {
        const position = index + 1;
        const inserted = insertTask.run(projectId, task.title, task.completed ? 1 : 0, task.priority,
          task.dueDate || null, task.notes, task.deleted ? 1 : 0, position);
        insertPosition.run(Number(inserted.lastInsertRowid), projectId, position);
      });
      database.exec('COMMIT');
    } catch {
      try { database.exec('ROLLBACK'); } catch {}
      return sendJson(res, 400, { error: 'Invalid project JSON' });
    }
    return sendJson(res, 201, { id: projectId, name: override });
  }
  const exportMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/export$/);
  if (exportMatch && req.method === 'GET') {
    const projectId = Number(exportMatch[1]);
    const project = database.prepare('SELECT name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    const tasks = database.prepare(`SELECT t.title, t.completed, t.priority, t.due_date AS dueDate,
        t.notes, t.deleted
      FROM tasks t LEFT JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
      WHERE t.project_id = ? ORDER BY COALESCE(p.position, t.sort_order), t.id`).all(projectId);
    const document = {
      format: 'workboard-project',
      version: 1,
      project: {
        name: project.name,
        archived: Boolean(project.archived),
        defaultPriority: project.defaultPriority || 'Normal',
        tasks: tasks.map((task) => ({
          title: task.title,
          completed: Boolean(task.completed),
          priority: task.priority || 'Normal',
          dueDate: task.dueDate || '',
          notes: (task.notes || '').replace(/\r\n?/g, '\n'),
          deleted: Boolean(task.deleted),
        })),
      },
    };
    res.writeHead(200, {
      'content-type': 'application/json; charset=utf-8',
      'content-disposition': 'attachment; filename="workboard-project.json"',
    });
    return res.end(JSON.stringify(document));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return sendJson(res, 400, { error: 'Project name is required' });
    const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveMatch && req.method === 'POST') {
    const archived = archiveMatch[2] === 'archive' ? 1 : 0;
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archived, Number(archiveMatch[1]));
    return result.changes ? sendJson(res, 200, { archived: Boolean(archived) }) : sendJson(res, 404, { error: 'Project not found' });
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (renameMatch && req.method === 'PATCH') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const id = Number(renameMatch[1]);
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(id);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(res, 403, { error: 'Archived project' });
    if (Object.hasOwn(data, 'name')) {
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return sendJson(res, 400, { error: 'Project name is required' });
      database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, id);
      return sendJson(res, 200, { id, name });
    }
    if (Object.hasOwn(data, 'defaultPriority')) {
      if (!['Low', 'Normal', 'High'].includes(data.defaultPriority)) return sendJson(res, 400, { error: 'Invalid default task priority' });
      database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(data.defaultPriority, id);
      return sendJson(res, 200, { id, defaultPriority: data.defaultPriority });
    }
    return sendJson(res, 400, { error: 'No project fields to update' });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && req.method === 'GET') {
    const project = database.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (project) project.archived = Boolean(project.archived);
    return project ? sendJson(res, 200, project) : sendJson(res, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) return sendJson(res, 404, { error: 'Project not found' });
    return sendJson(res, 200, database.prepare(`SELECT t.id, t.project_id AS projectId, t.title, t.completed, t.priority, t.due_date AS dueDate, t.notes, t.deleted
      FROM tasks t LEFT JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
      WHERE t.project_id = ? ORDER BY COALESCE(p.position, t.sort_order), t.id`).all(projectId));
  }
  if (tasksMatch && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const title = typeof data.title === 'string' ? data.title.trim() : '';
    if (!title) return sendJson(res, 400, { error: 'Task title is required' });
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id, archived, default_priority FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(res, 403, { error: 'Archived project' });
    const nextOrder = database.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS value FROM task_project_positions WHERE project_id = ?').get(projectId).value;
    const result = database.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, ?)').run(projectId, title, project.default_priority, nextOrder);
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const directoryView = document.querySelector('#task-directory');
const projectContainer = document.querySelector('#projects');
const form = document.querySelector('#create-form');
const nameInput = document.querySelector('#project-name');
const alert = document.querySelector('#form-alert');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const taskContainer = document.querySelector('#tasks');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const dueFromInput = document.querySelector('#due-from');
const dueThroughInput = document.querySelector('#due-through');
let appliedDueRange = { from: '', through: '' };
const defaultTaskPriority = document.querySelector('#default-task-priority');
const projectFilter = document.querySelector('#project-filter');
const renameForm = document.querySelector('#rename-form');
const renameInput = document.querySelector('#new-project-name');
const renameAlert = document.querySelector('#rename-alert');
const projectSearchInput = document.querySelector('#project-search');
const taskSearchInput = document.querySelector('#task-search');
let appliedProjectQuery = '';
let appliedTaskQuery = '';

function asciiLower(value) {
  return value.replace(/[A-Z]/g, (letter) => letter.toLowerCase());
}

function normalizeSearchText(value) {
  return asciiLower(value.replace(/[ \t]+/g, ' '));
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) return;
  const projects = await response.json();
  projectContainer.replaceChildren();
  for (const project of projects) {
    if (projectFilter.value === 'active' && project.archived) continue;
    if (projectFilter.value === 'archived' && !project.archived) continue;
    if (appliedProjectQuery && !normalizeSearchText(project.name).includes(normalizeSearchText(appliedProjectQuery))) continue;
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => {
      taskFilter.value = 'all';
      priorityFilter.value = 'all';
      appliedTaskQuery = '';
      taskSearchInput.value = '';
      history.pushState({}, '', `/projects/${project.id}`);
      showRoute();
    });
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const archive = document.createElement('button');
    archive.type = 'button';
    archive.textContent = project.archived ? 'Restore project' : 'Archive project';
    archive.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
      await loadProjects();
    });
    row.append(name, summary, open, archive);
    projectContainer.append(row);
  }
}

async function showRoute() {
  if (location.pathname === '/directory') {
    listView.hidden = true;
    detailView.hidden = true;
    directoryView.hidden = false;
    await loadDirectory();
    return;
  }
  directoryView.hidden = true;
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (!match) {
    detailView.hidden = true;
    listView.hidden = false;
    await loadProjects();
    return;
  }
  taskSearchInput.value = appliedTaskQuery;
  const response = await fetch(`/api/projects/${match[1]}`);
  if (!response.ok) {
    history.replaceState({}, '', '/');
    return showRoute();
  }
  const project = await response.json();
  document.querySelector('#download-project').dataset.exportUrl = `/api/projects/${project.id}/export`;
  appliedDueRange = { from: '', through: '' };
  dueFromInput.value = '';
  dueThroughInput.value = '';
  document.querySelector('#detail-name').textContent = project.name;
  document.querySelector('#archived-notice').hidden = !project.archived;
  renameInput.value = project.name;
  renameInput.disabled = project.archived;
  defaultTaskPriority.value = project.defaultPriority || 'Normal';
  defaultTaskPriority.disabled = project.archived;
  renameForm.querySelector('button[type="submit"]').disabled = project.archived;
  renameAlert.hidden = true;
  taskForm.querySelector('button[type="submit"]').disabled = project.archived;
  taskInput.disabled = project.archived;
  detailView.hidden = false;
  listView.hidden = true;
  await loadTasks(Number(match[1]), project.archived);
}

const directoryScope = document.querySelector('#directory-scope');
const directoryTaskFilter = document.querySelector('#directory-task-filter');
const directoryPriority = document.querySelector('#directory-priority');
const directorySearch = document.querySelector('#directory-search');
const directoryResults = document.querySelector('#directory-results');
const directoryEmpty = document.querySelector('#directory-empty');
const completeVisibleButton = document.querySelector('#complete-visible-tasks');
const reopenVisibleButton = document.querySelector('#reopen-visible-tasks');
let directoryQuery = '';
let directoryRange = { from: '', through: '' };
let visibleDirectoryTasks = [];

async function loadDirectory() {
  directoryEmpty.hidden = true;
  completeVisibleButton.disabled = true;
  reopenVisibleButton.disabled = true;
  const response = await fetch('/api/directory');
  if (!response.ok) return;
  const tasks = await response.json();
  visibleDirectoryTasks = tasks.filter((task) => {
    if ((directoryScope.value === 'Active' && task.archived) || (directoryScope.value === 'Archived' && !task.archived)) return false;
    if (directoryTaskFilter.value === 'Deleted' ? !task.deleted : task.deleted) return false;
    if (directoryTaskFilter.value === 'Open' && task.completed) return false;
    if (directoryTaskFilter.value === 'Completed' && !task.completed) return false;
    if (directoryPriority.value !== 'All' && task.priority !== directoryPriority.value) return false;
    if (directoryQuery && !normalizeSearchText(task.title).includes(normalizeSearchText(directoryQuery))) return false;
    if ((directoryRange.from || directoryRange.through) && !task.dueDate) return false;
    if (directoryRange.from && task.dueDate < directoryRange.from) return false;
    if (directoryRange.through && task.dueDate > directoryRange.through) return false;
    return true;
  });
  directoryResults.replaceChildren();
  for (const task of visibleDirectoryTasks) {
    const row = document.createElement('div');
    row.dataset.testid = 'directory-task-row';
    row.className = 'task-row directory-task-row';
    const title = document.createElement('span'); title.dataset.testid = 'directory-task-title'; title.textContent = task.title;
    const owner = document.createElement('span'); owner.dataset.testid = 'directory-project-name'; owner.textContent = task.projectName;
    const completion = document.createElement('span'); completion.dataset.testid = 'directory-task-completion'; completion.textContent = task.completed ? 'Completed' : 'Open';
    const priority = document.createElement('span'); priority.dataset.testid = 'directory-task-priority'; priority.textContent = task.priority;
    const due = document.createElement('span'); due.dataset.testid = 'directory-task-due-date'; due.textContent = task.dueDate || '';
    const notes = document.createElement('span'); notes.dataset.testid = 'directory-task-notes'; notes.textContent = task.notes || '';
    const open = document.createElement('button'); open.type = 'button'; open.textContent = 'Open project';
    open.addEventListener('click', () => {
      taskFilter.value = 'all'; priorityFilter.value = 'all';
      appliedTaskQuery = ''; taskSearchInput.value = '';
      history.pushState({}, '', `/projects/${task.projectId}`); showRoute();
    });
    row.append(title, owner, completion, priority, due, notes, open);
    directoryResults.append(row);
  }
  directoryEmpty.hidden = visibleDirectoryTasks.length !== 0;
  const eligible = directoryScope.value === 'Active' && directoryTaskFilter.value !== 'Deleted'
    ? visibleDirectoryTasks.filter((task) => !task.deleted) : [];
  completeVisibleButton.disabled = !eligible.some((task) => !task.completed);
  reopenVisibleButton.disabled = !eligible.some((task) => task.completed);
}

async function updateVisibleDirectoryTasks(completed) {
  const taskIds = visibleDirectoryTasks.filter((task) => !task.deleted && task.completed !== completed).map((task) => task.id);
  if (!taskIds.length) return;
  completeVisibleButton.disabled = true;
  reopenVisibleButton.disabled = true;
  const response = await fetch('/api/directory/bulk', {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ taskIds, completed }),
  });
  if (response.ok) await loadDirectory();
}
completeVisibleButton.addEventListener('click', () => updateVisibleDirectoryTasks(true));
reopenVisibleButton.addEventListener('click', () => updateVisibleDirectoryTasks(false));

for (const control of [directoryScope, directoryTaskFilter, directoryPriority]) control.addEventListener('change', loadDirectory);
document.querySelector('#directory-search-form').addEventListener('submit', (event) => { event.preventDefault(); directoryQuery = directorySearch.value.trim(); loadDirectory(); });
document.querySelector('#directory-apply-range').addEventListener('click', () => {
  const alert = document.querySelector('#directory-alert');
  const from = document.querySelector('#directory-due-from').value.trim();
  const through = document.querySelector('#directory-due-through').value.trim();
  if ((from && !validCalendarDate(from)) || (through && !validCalendarDate(through))) { alert.textContent = 'Due range must use valid YYYY-MM-DD dates'; alert.hidden = false; return; }
  if (from && through && from > through) { alert.textContent = 'Due from must not be after Due through'; alert.hidden = false; return; }
  directoryRange = { from, through }; alert.hidden = true; loadDirectory();
});
document.querySelector('#directory-button').addEventListener('click', () => {
  directoryScope.value = 'Active'; directoryTaskFilter.value = 'All'; directoryPriority.value = 'All';
  directorySearch.value = ''; directoryQuery = ''; directoryRange = { from: '', through: '' };
  document.querySelector('#directory-due-from').value = ''; document.querySelector('#directory-due-through').value = '';
  history.pushState({}, '', '/directory'); showRoute();
});
document.querySelector('#directory-back').addEventListener('click', () => { appliedProjectQuery = ''; projectSearchInput.value = ''; history.pushState({}, '', '/'); showRoute(); });

defaultTaskPriority.addEventListener('change', async () => {
  const projectId = location.pathname.match(/^\/projects\/(\d+)$/)?.[1];
  if (!projectId) return;
  const response = await fetch(`/api/projects/${projectId}`, {
    method: 'PATCH', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ defaultPriority: defaultTaskPriority.value }),
  });
  if (!response.ok) {
    const projectResponse = await fetch(`/api/projects/${projectId}`);
    if (projectResponse.ok) defaultTaskPriority.value = (await projectResponse.json()).defaultPriority || 'Normal';
  }
});

renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  const name = renameInput.value.trim();
